"""Tests for CodeMerger indentation preservation."""

from pipelex.core.concepts.structure_generation.code_merger import CodeMerger


class TestCodeMergerIndentation:
    """Test that CodeMerger preserves indentation of custom code."""

    def test_preserve_custom_fields_indentation_in_class(self):
        """Test that custom fields added inside class maintain their indentation."""
        existing_file = (
            "# <AUTOGENERATED>\n"
            "# The code between <AUTOGENERATED> and </AUTOGENERATED> is automatically generated.\n"
            "# Any changes between those tags will be overwritten on regeneration.\n"
            "from pydantic import Field\n"
            "\n\n"
            "class MatchAnalysis:\n"
            '    """Generated MatchAnalysis class"""\n'
            "\n"
            '    is_match: bool = Field(..., description="Match decision")\n'
            "# </AUTOGENERATED>\n"
            "\n"
            "    # Custom field added by user\n"
            '    custom_score: int = Field(..., description="Custom scoring")\n'
        )

        new_generated = (
            "# <AUTOGENERATED>\n"
            "# The code between <AUTOGENERATED> and </AUTOGENERATED> is automatically generated.\n"
            "# Any changes between those tags will be overwritten on regeneration.\n"
            "from pydantic import Field\n"
            "\n\n"
            "class MatchAnalysis:\n"
            '    """Generated MatchAnalysis class"""\n'
            "\n"
            '    is_match: bool = Field(..., description="Match decision")\n'
            '    match_score: float = Field(..., description="New field")\n'
            "# </AUTOGENERATED>\n"
        )

        result = CodeMerger.merge_with_existing(new_generated, existing_file)

        # New generated field should be present
        assert "match_score: float" in result

        # Custom field should be preserved WITH INDENTATION
        assert "    custom_score: int" in result

        # Custom field should still be part of the class (indented)
        lines = result.split("\n")
        custom_score_line_idx = next(index_line for index_line, line in enumerate(lines) if "custom_score" in line)
        # Line should start with 4 spaces (class member indentation)
        assert lines[custom_score_line_idx].startswith("    ")
        # Should NOT be at column 0
        assert not lines[custom_score_line_idx].startswith("custom_score")

    def test_preserve_custom_methods_indentation_in_class(self):
        """Test that custom methods added inside class maintain their indentation."""
        existing_file = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Person:\n"
            '    name: str = Field(..., description="Name")\n'
            "# </AUTOGENERATED>\n"
            "\n"
            "    # Custom method\n"
            "    def validate_name(self) -> bool:\n"
            "        return len(self.name) > 0\n"
        )

        new_generated = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Person:\n"
            '    name: str = Field(..., description="Name")\n'
            '    age: int = Field(..., description="Age")\n'
            "# </AUTOGENERATED>\n"
        )

        result = CodeMerger.merge_with_existing(new_generated, existing_file)

        # New field added
        assert "age: int" in result

        # Custom method preserved with indentation
        assert "    def validate_name(self)" in result
        assert "        return len(self.name) > 0" in result

    def test_preserve_module_level_code_after_class(self):
        """Test that module-level code after the class is preserved."""
        existing_file = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Person:\n"
            '    name: str = Field(..., description="Name")\n'
            "# </AUTOGENERATED>\n"
            "\n"
            "# Module-level function\n"
            "def validate_person(person):\n"
            "    return person.name != ''\n"
        )

        new_generated = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Person:\n"
            '    name: str = Field(..., description="Name")\n'
            '    age: int = Field(..., description="Age")\n'
            "# </AUTOGENERATED>\n"
        )

        result = CodeMerger.merge_with_existing(new_generated, existing_file)

        # Module-level function preserved at column 0
        assert "def validate_person(person):" in result
        lines = result.split("\n")
        validate_line_idx = next(index_line for index_line, line in enumerate(lines) if "def validate_person" in line)
        # Should be at column 0 (module level)
        assert lines[validate_line_idx].startswith("def validate_person")

    def test_complex_indentation_preservation(self):
        """Test complex scenario with mixed indentation levels."""
        existing_file = (
            "# Custom imports\n"
            "import re\n"
            "\n"
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Config:\n"
            '    version: str = Field(..., description="Version")\n'
            "# </AUTOGENERATED>\n"
            "\n"
            "    # Custom nested class inside Config\n"
            "    class Validator:\n"
            "        @staticmethod\n"
            "        def is_valid(config):\n"
            "            return config.version != ''\n"
            "\n"
            "# Module-level helper\n"
            "def helper():\n"
            "    pass\n"
        )

        new_generated = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Config:\n"
            '    version: str = Field(..., description="Version")\n'
            '    name: str = Field(..., description="Name")\n'
            "# </AUTOGENERATED>\n"
        )

        result = CodeMerger.merge_with_existing(new_generated, existing_file)

        # Custom import preserved
        assert "import re" in result

        # New field added
        assert "name: str" in result

        # Nested class preserved with proper indentation
        assert "    class Validator:" in result
        assert "        @staticmethod" in result
        assert "            return config.version" in result

        # Module-level function preserved
        assert "def helper():" in result

    def test_user_added_field_stays_indented_after_regeneration(self):
        """Test real-world scenario: user adds indented field, then regenerates."""
        # User's file after adding custom field (properly indented)
        existing_file = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class MatchAnalysis:\n"
            '    is_match: bool = Field(..., description="Match")\n'
            "# </AUTOGENERATED>\n"
            "    # Custom field added by user\n"
            '    custom_field: str = Field(..., description="My field")\n'
        )

        # New generation adds more fields
        new_generated = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class MatchAnalysis:\n"
            '    is_match: bool = Field(..., description="Match")\n'
            '    match_score: float = Field(..., description="Score")\n'
            "# </AUTOGENERATED>\n"
        )

        result = CodeMerger.merge_with_existing(new_generated, existing_file)

        # Verify new field is added
        assert "match_score: float" in result

        # Verify custom field is still indented (part of class)
        assert "    custom_field: str" in result

        # Verify it's not at column 0
        assert "\ncustom_field:" not in result  # Would indicate column 0

    def test_real_world_bug_field_loses_indentation_on_regeneration(self):
        """Test the exact bug reported: field at correct indentation loses it on regeneration."""
        # Existing file with properly indented custom field
        existing_file = (
            "# <AUTOGENERATED>\n"
            "# The code between <AUTOGENERATED> and </AUTOGENERATED> is automatically generated.\n"
            "# Any changes between those tags will be overwritten on regeneration.\n"
            "# To regenerate, use: pipelex build structures <library_dir>\n"
            "# You can add custom code above <AUTOGENERATED> or below </AUTOGENERATED>.\n"
            "from pydantic import Field\n"
            "from pipelex.core.stuffs import TextContent\n"
            "\n\n"
            "class JobOffer(TextContent):\n"
            '    """Generated JobOffer class"""\n'
            "\n"
            "# </AUTOGENERATED>\n"
            '    name: str = Field(..., description="Name of the job offer")\n'
        )

        # Regenerate with a new field
        new_generated = (
            "# <AUTOGENERATED>\n"
            "# The code between <AUTOGENERATED> and </AUTOGENERATED> is automatically generated.\n"
            "# Any changes between those tags will be overwritten on regeneration.\n"
            "# To regenerate, use: pipelex build structures <library_dir>\n"
            "# You can add custom code above <AUTOGENERATED> or below </AUTOGENERATED>.\n"
            "from pydantic import Field\n"
            "from pipelex.core.stuffs import TextContent\n"
            "\n\n"
            "class JobOffer(TextContent):\n"
            '    """Generated JobOffer class"""\n'
            "\n"
            '    salary: float = Field(..., description="Salary")\n'
            "# </AUTOGENERATED>\n"
        )

        result = CodeMerger.merge_with_existing(new_generated, existing_file)

        # New field should be present
        assert "salary: float" in result

        # CRITICAL: Custom field must still be indented (not at column 0)
        assert "    name: str = Field" in result

        # Verify it's NOT de-indented to column 0
        lines = result.split("\n")
        name_line = next(line for line in lines if "name: str" in line)
        assert name_line.startswith("    "), f"Field 'name' lost indentation! Line: {name_line!r}"
        assert not name_line.startswith("name:"), f"Field 'name' at column 0! Line: {name_line!r}"

    def test_no_blank_line_accumulation_on_multiple_regenerations(self):
        """Test that blank lines don't accumulate over multiple regenerations."""
        # First generation with custom field
        gen1_file = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Person:\n"
            '    name: str = Field(..., description="Name")\n'
            "# </AUTOGENERATED>\n"
            "\n"
            "    # Custom field\n"
            '    custom: str = Field(..., description="Custom")\n'
        )

        # Second regeneration
        gen2_code = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Person:\n"
            '    name: str = Field(..., description="Name")\n'
            '    age: int = Field(..., description="Age")\n'
            "# </AUTOGENERATED>\n"
        )

        result2 = CodeMerger.merge_with_existing(gen2_code, gen1_file)

        # Count blank lines after </AUTOGENERATED>
        after_marker = result2.split("# </AUTOGENERATED>")[1]
        blank_line_count_2 = len([line for line in after_marker.split("\n")[:5] if line.strip() == ""])

        # Third regeneration
        gen3_code = (
            "# <AUTOGENERATED>\n"
            "from pydantic import Field\n"
            "\n\n"
            "class Person:\n"
            '    name: str = Field(..., description="Name")\n'
            '    age: int = Field(..., description="Age")\n'
            '    email: str = Field(..., description="Email")\n'
            "# </AUTOGENERATED>\n"
        )

        result3 = CodeMerger.merge_with_existing(gen3_code, result2)

        # Count blank lines after </AUTOGENERATED>
        after_marker = result3.split("# </AUTOGENERATED>")[1]
        blank_line_count_3 = len([line for line in after_marker.split("\n")[:5] if line.strip() == ""])

        # Blank line count should NOT increase
        assert blank_line_count_3 == blank_line_count_2, f"Blank lines accumulated! Gen2: {blank_line_count_2}, Gen3: {blank_line_count_3}"
